import React, { useEffect, useState } from "react";
import axios from "axios";
import { toast } from "react-toastify";

const [faqs, setFaqs] = useState([]);
const [loading, setLoading] = useState(true);

const [search, setSearch] = useState("");
const [category, setCategory] = useState("");

const [showModal, setShowModal] = useState(false);
const [showDeleteModal, setShowDeleteModal] = useState(false);

const [editingFAQ, setEditingFAQ] = useState(null);
const [selectedFAQ, setSelectedFAQ] = useState(null);

const [question, setQuestion] = useState("");
const [answer, setAnswer] = useState("");
const [faqCategory, setFaqCategory] = useState("Orders");

const fetchFAQs = async () => {
  try {
    setLoading(true);

    const { data } = await axios.get("/api/v1/faqs");

    if (data.success) {
      setFaqs(data.faqs);
    }
  } catch (error) {
    console.log(error);
    toast.error("Failed to load FAQs");
  } finally {
    setLoading(false);
  }
};

useEffect(() => {
  fetchFAQs();
}, []);

const filteredFAQs = faqs.filter((faq) => {
  const matchesSearch =
    faq.question.toLowerCase().includes(search.toLowerCase()) ||
    faq.answer.toLowerCase().includes(search.toLowerCase());

  const matchesCategory =
    category === "" || faq.category === category;

  return matchesSearch && matchesCategory;
});

<div className="grid grid-cols-2 lg:grid-cols-4 gap-5 mb-8">

  <div className="bg-white rounded-xl shadow p-5">
    <p className="text-gray-500">Total FAQs</p>
    <h2 className="text-3xl font-bold text-blue-600">
      {faqs.length}
    </h2>
  </div>

  <div className="bg-white rounded-xl shadow p-5">
    <p className="text-gray-500">Categories</p>
    <h2 className="text-3xl font-bold text-green-600">
      {new Set(faqs.map(f => f.category)).size}
    </h2>
  </div>

  <div className="bg-white rounded-xl shadow p-5">
    <p className="text-gray-500">Orders FAQ</p>
    <h2 className="text-3xl font-bold text-orange-500">
      {faqs.filter(f=>f.category==="Orders").length}
    </h2>
  </div>

  <div className="bg-white rounded-xl shadow p-5">
    <p className="text-gray-500">Payment FAQ</p>
    <h2 className="text-3xl font-bold text-purple-600">
      {faqs.filter(f=>f.category==="Payment").length}
    </h2>
  </div>
  <div className="flex flex-col md:flex-row gap-4 mb-8">

  <input
    type="text"
    placeholder="Search FAQs..."
    value={search}
    onChange={(e) => setSearch(e.target.value)}
    className="
      flex-1
      border
      rounded-xl
      p-3
      focus:ring-2
      focus:ring-blue-500
      outline-none
    "
  />

  <select
    value={category}
    onChange={(e) => setCategory(e.target.value)}
    className="
      border
      rounded-xl
      p-3
      md:w-56
    "
  >
    <option value="">All Categories</option>
    <option value="Orders">Orders</option>
    <option value="Payment">Payment</option>
    <option value="Shipping">Shipping</option>
    <option value="Returns">Returns</option>
    <option value="Coupons">Coupons</option>
    <option value="Books">Books</option>
  </select>

  <button
    onClick={() => {
      setEditingFAQ(null);
      setQuestion("");
      setAnswer("");
      setFaqCategory("Orders");
      setShowModal(true);
    }}
    className="
      bg-blue-600
      hover:bg-blue-700
      text-white
      px-6
      py-3
      rounded-xl
      font-semibold
    "
  >
    + Add FAQ
  </button>

</div>
{loading ? (

<div className="text-center py-20">

<h2 className="text-xl font-semibold">
Loading FAQs...
</h2>

</div>

) : filteredFAQs.length === 0 ? (

<div className="bg-white rounded-xl shadow p-10 text-center">

<h2 className="text-xl font-semibold">
No FAQs Found
</h2>

<p className="text-gray-500 mt-2">
Try changing the search or category.
</p>

</div>

) : (

<>
</>
)}

</div>
